import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { asString, useSearchParam } from '../../url/useSearchParam';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { useGradeCodes } from '../grades/useGrades';
import { useSheetToday } from '../sheet/useSheetToday';
import { NA } from './due';
import { ImportRates } from './ImportRates';
import { RatePreview } from './RatePreview';
import { rateOn, ratesKey, useRates, type Rate } from './useRates';

const MONTHS = ['01', '02', '03', '04', '05', '06', '07', '08', '09', '10', '11', '12'];

// The rate in force on the sheet's today for each grade (n/a where none applies), every rate set with
// the dates it applies from and through, and the form that sets one (a blank from-date: from the
// beginning of time; a blank to-date: no end; one already there from the same date is kept as an older
// version and the row shows its version count), a calendar of each grade's rate in force on the first day of
// each month of the sheet's today's year (n/a where none), and a preview of a candidate rate for a grade.
export function RatePanel() {
  const [sheet] = useSearchParam('sheet', asString);
  const grades = useGradeCodes(sheet);
  const [user] = useSearchParam('user', asString);
  const rates = useRates(sheet);
  const [grade, setGrade] = useState<string>('A');
  const today = useSheetToday(sheet);
  const months = today ? MONTHS.map((m) => `${today.slice(0, 4)}-${m}`) : [];
  const [pct, setPct] = useState('');
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');
  const queryClient = useQueryClient();
  const submitOnce = useSubmitOnce();
  const save = useMutation({
    mutationFn: (body: { grade: string; rate: string; from: string; to: string }) =>
      postJson<Rate[]>(`/api/sheets/${encodeURIComponent(sheet)}/rates`, { ...body, user }),
    onSuccess: (saved) => {
      setPct('');
      setFrom('');
      setTo('');
      queryClient.setQueryData(ratesKey(sheet), saved);
    },
  });
  return (
    <>
      <table data-testid="rates">
        <thead>
          <tr>
            <th>Grade</th>
            <th>Rate % today</th>
          </tr>
        </thead>
        <tbody>
          {grades.map((g) => (
            <tr key={g}>
              <td>{g}</td>
              <td data-testid={`rate-current-${g}`}>{rateOn(rates, g, today) ?? NA}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <table data-testid="rate-calendar">
        <thead>
          <tr>
            <th>Grade</th>
            {months.map((m) => (
              <th key={m}>{m}</th>
            ))}
          </tr>
        </thead>
        <tbody>
          {grades.map((g) => (
            <tr key={g}>
              <td>{g}</td>
              {months.map((m) => (
                <td key={m} data-testid={`rate-month-${g}-${m}`}>{rateOn(rates, g, `${m}-01`) ?? NA}</td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
      <table data-testid="rate-list">
        <thead>
          <tr>
            <th>Grade</th>
            <th>From</th>
            <th>To</th>
            <th>Rate %</th>
            <th>Versions</th>
          </tr>
        </thead>
        <tbody>
          {rates.filter((r) => r.level === undefined).map((r) => (
            <tr key={`${r.grade}-${r.from}`} data-testid={`rate-row-${r.grade}-${r.from || 'start'}`}>
              <td>{r.grade}</td>
              <td data-testid="rate-from">{r.from || 'start'}</td>
              <td data-testid="rate-to">{r.to}</td>
              <td data-testid="rate-pct">{r.rate}</td>
              <td data-testid="rate-version">{r.version}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <form
        data-testid="rate-form"
        onSubmit={(e) => {
          e.preventDefault();
          submitOnce(() => {
            save.reset();
            return save.mutateAsync({ grade, rate: pct.trim(), from: from.trim(), to: to.trim() });
          });
        }}
      >
        <select
          data-testid="rate-form-grade"
          value={grade}
          onChange={(e) => {
            setGrade(e.target.value);
            save.reset();
          }}
        >
          {grades.map((g) => (
            <option key={g} value={g}>{g}</option>
          ))}
        </select>{' '}
        <input
          data-testid="rate-form-pct"
          value={pct}
          placeholder="Rate %"
          onChange={(e) => {
            setPct(e.target.value);
            save.reset();
          }}
        />{' '}
        <input
          data-testid="rate-form-from"
          value={from}
          placeholder="From (YYYY-MM-DD, blank: always)"
          onChange={(e) => {
            setFrom(e.target.value);
            save.reset();
          }}
        />{' '}
        <input
          data-testid="rate-form-to"
          value={to}
          placeholder="To (YYYY-MM-DD, blank: no end)"
          onChange={(e) => {
            setTo(e.target.value);
            save.reset();
          }}
        />{' '}
        <button type="submit" data-testid="rate-form-submit">Set rate</button>
        {save.isError && <span data-testid="rate-form-error" role="alert"> Could not set the rate: it must be a percent of 0.00 or more with at most two decimals, from a valid date (YYYY-MM-DD) or none, to a valid date not before it or none.</span>}
      </form>
      <ImportRates />
      <RatePreview />
    </>
  );
}
import { useMemo } from 'react';
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { readPath, useAsOf } from '../asof/useAsOf';

/** A grade's rate: a percent shown with two decimals ("12.50"), in force from a date (YYYY-MM-DD;
 *  "" for from the beginning of time) through a date ("" for no end), and its version: how many times a
 *  rate has been set for the grade and from-date, this the newest. One inherited from an ancestor
 *  sheet has its level: 1 the parent, 2 the parent's parent, 3 the one above, then a clone's source and its own
 *  ancestors in turn; the sheet's own have none.
 *  afterMark is 0 for a rate applying to every claim; a forward-only one (saved with a from-date on or after the
 *  sheet's today) applies only to claims whose rateMark is greater, the others falling back to the older versions
 *  it replaced (earlier, newest first). */
export type Rate = {
  grade: string;
  rate: string;
  from: string;
  to: string;
  version: number;
  level?: number;
  afterMark?: number;
  earlier?: { rate: string; to: string; afterMark: number }[];
};

/** Whether a rate (version) with this mark applies to a claim with that one; no claim mark: the rate in force,
 *  without regard to forward-only rates (as the rates panel, the rate preview and the rate calendar show it). */
function applies(afterMark: number | undefined, claimMark: number | undefined): boolean {
  return !afterMark || claimMark === undefined || claimMark > afterMark;
}

export const ratesKey = (sheet: string, asOf = '') => ['sheet', sheet, 'rates', asOf] as const;

export const inheritedRatesKey = (sheet: string, asOf = '') => ['sheet', sheet, 'inherited-rates', asOf] as const;

/** The sheet's own rates, by grade then from-date (from the beginning of time first), followed by
 *  its ancestors' (nearest first), each with its level. */
export function useRates(sheet: string): Rate[] {
  const asOf = useAsOf();
  const { data } = useQuery({
    queryKey: ratesKey(sheet, asOf),
    queryFn: () => getJson<Rate[]>(readPath(`/api/sheets/${encodeURIComponent(sheet)}/rates`, asOf)),
    enabled: sheet !== '',
  });
  const { data: inherited } = useQuery({
    queryKey: inheritedRatesKey(sheet, asOf),
    queryFn: () => getJson<Rate[][]>(readPath(`/api/sheets/${encodeURIComponent(sheet)}/inherited-rates`, asOf)),
    enabled: sheet !== '',
  });
  return useMemo(
    () => [...(data ?? []), ...(inherited ?? []).flatMap((rates, i) => rates.map((r) => ({ ...r, level: i + 1 })))],
    [data, inherited],
  );
}

/** One sheet's grade rate in force on a date (for a claim with a mark: of the versions that apply to it): the one with
 *  the latest from-date on or before it; undefined when none applies, or when that one's to-date is before the date. */
function ownRateOn(rates: Rate[], grade: string, date: string, level: number, mark?: number): string | undefined {
  let found: { from: string; rate: string; to: string } | undefined;
  for (const r of rates) {
    if ((r.level ?? 0) !== level || r.grade !== grade || r.from > date || (found !== undefined && r.from < found.from)) continue;
    const version = [r, ...(r.earlier ?? [])].find((v) => applies(v.afterMark, mark));
    if (version !== undefined) found = { from: r.from, rate: version.rate, to: version.to };
  }
  if (found === undefined || (found.to !== '' && found.to < date)) return undefined;
  return found.rate;
}

/** The grade's rate in force on a date: the sheet's own (see ownRateOn); when it has none, its parent's,
 *  then the parent's parent's, up to three levels up, then a clone's source's and so on (each a level further);
 *  undefined when none has one (or the date is not known yet). */
export function rateOn(rates: Rate[], grade: string, date: string | undefined, mark?: number): string | undefined {
  if (date === undefined) return undefined;
  const levels = rates.reduce((max, r) => Math.max(max, r.level ?? 0), 0);
  for (let level = 0; level <= levels; level++) {
    const found = ownRateOn(rates, grade, date, level, mark);
    if (found !== undefined) return found;
  }
  return undefined;
}

/** The grade's rate that applies to a claim on its date (see rateOn): a forward-only rate only when the claim
 *  arrived on the sheet after it was saved. */
export function claimRate(rates: Rate[], grade: string, claim: { date: string; rateMark?: number }): string | undefined {
  return rateOn(rates, grade, claim.date, claim.rateMark ?? 0);
}

